import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Tool, Point, EditMode, FloatingObject } from '../types';
import { samService } from '../services/samService';
import { RawImage } from '@huggingface/transformers';
import { TransformNode } from './TransformNode';
import { extractFloatingObject } from '../utils/imageUtils';

interface EditorProps {
  image: string;
  tool: Tool;
  brushSize: number;
  onMaskUpdate: (canvas: HTMLCanvasElement | null) => void;
  status: string;
  setStatus: (s: string) => void;
  editMode: EditMode;
  floatingObject: FloatingObject | null;
  setFloatingObject: (obj: FloatingObject | null) => void;
  isGenerating?: boolean;
  onPromptRequest?: (pos: { x: number; y: number }) => void;
}

export const Editor: React.FC<EditorProps> = ({ 
  image, 
  tool, 
  brushSize, 
  onMaskUpdate,
  setStatus,
  editMode,
  floatingObject,
  setFloatingObject,
  isGenerating,
  onPromptRequest
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const baseCanvasRef = useRef<HTMLCanvasElement>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement>(null);
  const tempCanvasRef = useRef<HTMLCanvasElement>(null);

  // Transform State
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const [isPanning, setIsPanning] = useState(false);
  const [isSpacePressed, setIsSpacePressed] = useState(false);

  // Interaction State
  const [isDrawing, setIsDrawing] = useState(false);
  const [samReady, setSamReady] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [isHoveringImage, setIsHoveringImage] = useState(false);

  const decodeState = useRef({
    isDecoding: false,
    decodePending: false,
    lastPoint: null as Point | null,
  });

  // Draw base image and hole
  useEffect(() => {
    if (!image || !baseCanvasRef.current) return;
    const img = new Image();
    img.src = image;
    img.onload = () => {
      const canvas = baseCanvasRef.current!;
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);

      if (floatingObject) {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.drawImage(floatingObject.originalMask, 0, 0);
        ctx.globalCompositeOperation = 'source-over';
      }

      // Auto-fit on initial load
      resetViewport();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [image, floatingObject?.originalMask]);

  // Attach non-passive wheel listener for zoom
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (e.ctrlKey || e.metaKey) {
        const delta = -e.deltaY;
        const targetZoomFactor = Math.pow(1.1, delta / 100);

        setTransform(prev => {
          const newScale = Math.max(0.1, Math.min(10, prev.scale * targetZoomFactor));
          const actualZoom = newScale / prev.scale;

          const rect = container.getBoundingClientRect();
          const relX = e.clientX - rect.left - rect.width / 2;
          const relY = e.clientY - rect.top - rect.height / 2;

          const newX = relX - (relX - prev.x) * actualZoom;
          const newY = relY - (relY - prev.y) * actualZoom;

          return { x: newX, y: newY, scale: newScale };
        });
      } else {
        setTransform(prev => ({
          ...prev,
          x: prev.x - e.deltaX,
          y: prev.y - e.deltaY
        }));
      }
    };

    container.addEventListener('wheel', handleWheel, { passive: false });
    return () => container.removeEventListener('wheel', handleWheel);
  }, []);

  // Handle Global Keys
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') setIsSpacePressed(true);
      if (e.code === 'Escape') {
        if (floatingObject) {
          setFloatingObject(null);
        }
        const mainCanvas = maskCanvasRef.current;
        if (mainCanvas) {
          const ctx = mainCanvas.getContext('2d');
          ctx?.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
        }
        onMaskUpdate(null);

        if (tool === 'sam') {
          clearTempMask();
        }
        setIsDrawing(false);
        setIsPanning(false);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space') setIsSpacePressed(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [floatingObject, setFloatingObject, onMaskUpdate, tool]);

  // Clear mask when editMode changes
  useEffect(() => {
    const mainCanvas = maskCanvasRef.current;
    if (mainCanvas) {
      const ctx = mainCanvas.getContext('2d');
      ctx?.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
    }
    const tempCanvas = tempCanvasRef.current;
    if (tempCanvas) {
      const ctx = tempCanvas.getContext('2d');
      ctx?.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
    }
    decodeState.current.lastPoint = null;
    decodeState.current.decodePending = false;
    onMaskUpdate(null);
    setIsDrawing(false);
    setIsPanning(false);
  }, [editMode, onMaskUpdate]);

  // SAM Initialization
  useEffect(() => {
    if (!image) return;

    setSamReady(false);

    // Immediately clear masks when image changes
    if (maskCanvasRef.current && tempCanvasRef.current) {
      const mCtx = maskCanvasRef.current.getContext('2d');
      const tCtx = tempCanvasRef.current.getContext('2d');
      mCtx?.clearRect(0, 0, maskCanvasRef.current.width, maskCanvasRef.current.height);
      tCtx?.clearRect(0, 0, tempCanvasRef.current.width, tempCanvasRef.current.height);
    }
    decodeState.current.lastPoint = null;
    decodeState.current.decodePending = false;
    onMaskUpdate(null);

    let isMounted = true;
    const initSam = async () => {
      setStatus("Loading AI models...");
      try {
        await samService.load();
        setStatus("Processing image structure...");
        const meta = await samService.setReferenceImage(image);
        if (isMounted) {
          setSamReady(true);
          setStatus("Ready to edit");
          if (maskCanvasRef.current && tempCanvasRef.current) {
            maskCanvasRef.current.width = meta.width;
            maskCanvasRef.current.height = meta.height;
            tempCanvasRef.current.width = meta.width;
            tempCanvasRef.current.height = meta.height;
          }
        }
      } catch (err) {
        console.error(err);
        setStatus("Model failed to load. Check WebGPU support.");
      }
    };
    initSam();
    return () => { isMounted = false; };
  }, [image, setStatus]);

  const drawMask = useCallback((mask: RawImage, scores: Float32Array) => {
    const canvas = tempCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let bestIndex = 0;
    for (let i = 1; i < scores.length; ++i) {
      if (scores[i] > scores[bestIndex]) bestIndex = i;
    }

    if (scores[bestIndex] < 0.4) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      return;
    }

    const imageData = ctx.createImageData(canvas.width, canvas.height);
    const numMasks = scores.length;
    const w = canvas.width;
    const h = canvas.height;

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (mask.data[numMasks * i + bestIndex] === 1) {
          let isBorder = false;
          if (x === 0 || x === w - 1 || y === 0 || y === h - 1) {
             isBorder = true;
          } else {
             if (mask.data[numMasks * (i - 1) + bestIndex] === 0 ||
                 mask.data[numMasks * (i + 1) + bestIndex] === 0 ||
                 mask.data[numMasks * (i - w) + bestIndex] === 0 ||
                 mask.data[numMasks * (i + w) + bestIndex] === 0) {
                isBorder = true;
             }
          }

          const offset = 4 * i;
          if (isBorder) {
            const isBlack = (x + y) % 8 < 4;
            imageData.data[offset] = isBlack ? 0 : 255;
            imageData.data[offset + 1] = isBlack ? 0 : 255;
            imageData.data[offset + 2] = isBlack ? 0 : 255;
            imageData.data[offset + 3] = 255;
          } else {
            imageData.data[offset] = 255;
            imageData.data[offset + 1] = 255;
            imageData.data[offset + 2] = 255;
            imageData.data[offset + 3] = 255;
          }
        }
      }
    }
    ctx.putImageData(imageData, 0, 0);
  }, []);

  const decode = useCallback(async () => {
    const s = decodeState.current;
    if (s.isDecoding || !s.lastPoint || !samReady) {
      s.decodePending = !!s.lastPoint;
      return;
    }
    s.isDecoding = true;
    try {
      const { mask, scores } = await samService.generateMask(s.lastPoint);
      if (s.lastPoint) {
        drawMask(mask, scores);
      }
    } catch (err) {
      console.error(err);
    } finally {
      s.isDecoding = false;
      if (s.decodePending && s.lastPoint) {
        s.decodePending = false;
        decode();
      }
    }
  }, [samReady, drawMask]);

  const clearTempMask = () => {
    const canvas = tempCanvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      ctx?.clearRect(0, 0, canvas.width, canvas.height);
    }
    decodeState.current.lastPoint = null;
    decodeState.current.decodePending = false;
  };

  const getNormalizedCoords = (e: React.MouseEvent | MouseEvent): [number, number] | null => {
    const canvas = baseCanvasRef.current;
    if (!canvas) return null;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    if (x < 0 || x > 1 || y < 0 || y > 1) return null;
    return [x, y];
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePos({ x: e.clientX, y: e.clientY });

    if (isPanning || (isSpacePressed && isDrawing)) {
      setTransform(prev => ({
        ...prev,
        x: prev.x + e.movementX,
        y: prev.y + e.movementY
      }));
      return;
    }

    const coords = getNormalizedCoords(e);
    if (!coords) {
      setIsHoveringImage(false);
      if (tool === 'sam') clearTempMask();
      return;
    }

    setIsHoveringImage(true);

    if (tool === 'sam' && samReady && !floatingObject) {
      decodeState.current.lastPoint = { position: coords, label: 1 };
      decode();
    } else if (tool === 'brush' && isDrawing && !floatingObject) {
      const canvas = maskCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const pxX = coords[0] * canvas.width;
      const pxY = coords[1] * canvas.height;
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(pxX, pxY, brushSize, 0, Math.PI * 2);
      ctx.fill();
      onMaskUpdate(canvas);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button === 1 || (e.button === 0 && isSpacePressed)) {
      setIsPanning(true);
      return;
    }

    if (e.button !== 0) return;
    if (floatingObject) return;

    if (tool === 'brush') {
      setIsDrawing(true);
      handleMouseMove(e);
    } else if (tool === 'sam' && samReady) {
      const mainCanvas = maskCanvasRef.current;
      const tempCanvas = tempCanvasRef.current;
      const baseCanvas = baseCanvasRef.current;

      if (mainCanvas && tempCanvas && baseCanvas) {
        const ctx = mainCanvas.getContext('2d');
        if (ctx) {
          ctx.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
          ctx.drawImage(tempCanvas, 0, 0);
          onMaskUpdate(mainCanvas);

          const tempCtx = tempCanvas.getContext('2d');
          tempCtx?.clearRect(0, 0, tempCanvas.width, tempCanvas.height);

          if (editMode === 'move') {
            const obj = extractFloatingObject(baseCanvas, mainCanvas);
            if (obj) {
              setFloatingObject(obj);
              ctx.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
              onMaskUpdate(mainCanvas);
              onPromptRequest?.({ x: e.clientX, y: e.clientY });
            }
          } else {
            onPromptRequest?.({ x: e.clientX, y: e.clientY });
          }
        }
      }
    }
  };

  const handleMouseUp = useCallback((e: MouseEvent | React.MouseEvent) => {
    if (isDrawing && tool === 'brush' && !floatingObject) {
      if (editMode === 'move') {
        const mainCanvas = maskCanvasRef.current;
        const baseCanvas = baseCanvasRef.current;
        if (mainCanvas && baseCanvas) {
          const obj = extractFloatingObject(baseCanvas, mainCanvas);
          if (obj) {
            setFloatingObject(obj);
            const ctx = mainCanvas.getContext('2d');
            ctx?.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
            onMaskUpdate(mainCanvas);
            onPromptRequest?.({ x: e.clientX, y: e.clientY });
          }
        }
      } else {
        onPromptRequest?.({ x: e.clientX, y: e.clientY });
      }
    }
    setIsDrawing(false);
    setIsPanning(false);
  }, [isDrawing, tool, editMode, floatingObject, setFloatingObject, onMaskUpdate, onPromptRequest]);

  useEffect(() => {
    window.addEventListener('mouseup', handleMouseUp);
    return () => window.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseUp]);

  const handleMouseLeave = () => {
    setIsHoveringImage(false);
    if (tool === 'sam' && !isDrawing) clearTempMask();
  };

  const getScreenBrushSize = () => {
    const canvas = baseCanvasRef.current;
    const maskCanvas = maskCanvasRef.current;
    if (!canvas || !maskCanvas) return brushSize;
    const scale = canvas.getBoundingClientRect().width / maskCanvas.width;
    return brushSize * scale;
  };

  const resetViewport = () => {
    const container = containerRef.current;
    const canvas = baseCanvasRef.current;
    if (container && canvas && canvas.width > 0 && canvas.height > 0) {
      const containerRect = container.getBoundingClientRect();
      const scaleX = (containerRect.width * 0.9) / canvas.width;
      const scaleY = (containerRect.height * 0.9) / canvas.height;
      const scale = Math.min(scaleX, scaleY, 1);
      setTransform({ x: 0, y: 0, scale });
    } else {
      setTransform({ x: 0, y: 0, scale: 1 });
    }
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full bg-zinc-900 overflow-hidden flex items-center justify-center group select-none ${
        (isPanning || isSpacePressed) ? 'cursor-grab active:cursor-grabbing' : (floatingObject || isGenerating ? 'cursor-default' : 'cursor-none')
      }`}
      onMouseMove={handleMouseMove}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div 
        className="relative will-change-transform flex items-center justify-center"
        style={{ 
          transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
          transition: isPanning ? 'none' : 'transform 0.05s linear'
        }}
      >
        <div className="relative">
          <canvas 
            ref={baseCanvasRef} 
            className="pointer-events-none select-none bg-checkerboard block" 
          />
          <canvas 
            ref={maskCanvasRef} 
            className={`absolute inset-0 w-full h-full pointer-events-none transition-all duration-500 ${isGenerating ? 'animate-magical-wave' : ''}`} 
            style={{ display: floatingObject ? 'none' : 'block', opacity: isGenerating ? undefined : 0.65 }}
          />
          <canvas 
            ref={tempCanvasRef} 
            className="absolute inset-0 w-full h-full pointer-events-none" 
            style={{ display: floatingObject || isGenerating ? 'none' : 'block', opacity: 0.65 }}
          />
          {floatingObject && (
            <TransformNode
              floatingObject={floatingObject}
              onChange={setFloatingObject}
              containerScale={transform.scale}
              isGenerating={isGenerating}
            />
          )}
        </div>
      </div>

      {!isPanning && !isSpacePressed && isHoveringImage && !floatingObject && !isGenerating && (
        <div 
          className="fixed pointer-events-none z-50 rounded-full border border-white mix-blend-difference transition-[opacity] duration-150"
          style={{
            left: mousePos.x,
            top: mousePos.y,
            width: tool === 'brush' ? getScreenBrushSize() * 2 : 12,
            height: tool === 'brush' ? getScreenBrushSize() * 2 : 12,
            transform: 'translate(-50%, -50%)',
            backgroundColor: tool === 'brush' ? 'rgba(255, 255, 255, 0.4)' : 'transparent',
            boxShadow: '0 0 0 1px rgba(0,0,0,0.5)'
          }}
        >
          {tool === 'sam' && <div className="absolute inset-0 m-auto w-1.5 h-1.5 bg-white rounded-full" />}
        </div>
      )}

      {/* Navigation & Controls Overlay */}
      <div className="absolute top-4 left-4 flex flex-col gap-3 pointer-events-none">
        <div className="bg-white text-black px-4 py-2 border-[3px] border-black text-xl font-bold uppercase tracking-widest shadow-[4px_4px_0px_#000]">
          ZOOM {Math.round(transform.scale * 100)}%
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); resetViewport(); }}
          className="pointer-events-auto bg-[#e0e0e0] text-black hover:bg-black hover:text-white border-[3px] border-black px-4 py-2 text-xl font-bold uppercase tracking-widest transition-none shadow-[4px_4px_0px_#000]"
        >
          RESET
        </button>
      </div>

      <div className="absolute top-4 right-4 bg-white text-black px-4 py-2 border-[3px] border-black text-lg font-bold uppercase tracking-widest pointer-events-none shadow-[4px_4px_0px_#000] -translate-y-2 opacity-0 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-200">
        <span className="bg-black text-white px-2 py-1 mr-2">{tool === 'brush' ? `BRUSH ${brushSize}` : 'SMART'}</span>
        SPACE PAN / SCROLL ZOOM
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { FloatingObject } from '../types';
import { RotateCw } from 'lucide-react';

interface Props {
  floatingObject: FloatingObject;
  onChange: (obj: FloatingObject) => void;
  containerScale: number;
  isGenerating?: boolean;
}

export const TransformNode: React.FC<Props> = ({ floatingObject, onChange, containerScale, isGenerating }) => {
  const [activeAction, setActiveAction] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [startObj, setStartObj] = useState<FloatingObject | null>(null);

  useEffect(() => {
    if (!activeAction) return;

    const handlePointerMove = (e: PointerEvent) => {
      if (!startObj) return;
      const dx = (e.clientX - startPos.x) / containerScale;
      const dy = (e.clientY - startPos.y) / containerScale;

      let newObj = { ...startObj };

      if (activeAction === 'move') {
        newObj.x += dx;
        newObj.y += dy;
      } else if (activeAction === 'scale') {
        // Calculate new scale based on Euclidean distance from center vs original
        // Center in screen space when interaction started
        const centerX = startPos.x - dx; // Rough approximation, but we can just use movement magnitude
        // Simple scale logic: if you drag out from center it scales up
        const moveDist = dx + dy; // TopLeft -> BottomRight is positive dx, dy
        let scaleChange = moveDist / startObj.width;
        if (e.clientX < startPos.x && e.clientY < startPos.y) {
           scaleChange = -scaleChange; // Invert for top-left
        } else if (e.clientX > startPos.x && e.clientY < startPos.y) {
           scaleChange = (dx - dy) / startObj.width;
        } else if (e.clientX < startPos.x && e.clientY > startPos.y) {
           scaleChange = (-dx + dy) / startObj.width;
        }

        newObj.scale = Math.max(0.1, startObj.scale + scaleChange);
      } else if (activeAction === 'rotate') {
        // Simplified rotation based on horizontal drag
        newObj.rotation += dx;
      }

      onChange(newObj);
    };

    const handlePointerUp = () => {
      setActiveAction(null);
    };

    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);

    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [activeAction, startPos, startObj, containerScale, onChange]);

  const handlePointerDown = (e: React.PointerEvent, action: string) => {
    e.stopPropagation();
    setActiveAction(action);
    setStartPos({ x: e.clientX, y: e.clientY });
    setStartObj(floatingObject);
  };

  return (
    <div
      style={{
        position: 'absolute',
        left: floatingObject.x,
        top: floatingObject.y,
        width: floatingObject.width,
        height: floatingObject.height,
        transform: `rotate(${floatingObject.rotation}deg) scale(${floatingObject.scale})`,
        transformOrigin: 'center center',
        cursor: activeAction === 'move' ? 'grabbing' : 'grab',
        border: isGenerating ? 'none' : '2px dashed rgba(255, 255, 255, 0.8)',
        boxShadow: isGenerating ? 'none' : '0 0 0 1px rgba(0, 0, 0, 0.5)',
        touchAction: 'none'
      }}
      onPointerDown={(e) => !isGenerating && handlePointerDown(e, 'move')}
    >
      <img 
        src={floatingObject.canvas.toDataURL()} 
        className={isGenerating ? "animate-google-glow" : ""}
        style={{ width: '100%', height: '100%', pointerEvents: 'none' }} 
        alt="Extracted"
      />

      {!isGenerating && (
        <>
          {/* Handle styles */}
          {[
            { top: -6, left: -6, cursor: 'nwse-resize' },
            { top: -6, right: -6, cursor: 'nesw-resize' },
            { bottom: -6, left: -6, cursor: 'nesw-resize' },
            { bottom: -6, right: -6, cursor: 'nwse-resize' }
          ].map((pos, i) => (
            <div
              key={i}
              style={{
                position: 'absolute',
                ...pos,
                width: 12,
                height: 12,
                backgroundColor: 'white',
                border: '1px solid black',
                cursor: pos.cursor,
              }}
              onPointerDown={(e) => handlePointerDown(e, 'scale')}
            />
          ))}

          {/* Rotate Handle (Top Center) */}
          <div
            style={{
              position: 'absolute',
              top: -30,
              left: '50%',
              transform: 'translateX(-50%)',
              width: 24,
              height: 24,
              backgroundColor: 'white',
              border: '1px solid black',
              cursor: 'ew-resize',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'black'
            }}
            onPointerDown={(e) => handlePointerDown(e, 'rotate')}
          >
            <RotateCw size={14} />
          </div>

          {/* Connecting line for rotate handle */}
          <div style={{
            position: 'absolute',
            top: -18,
            left: '50%',
            width: 1,
            height: 18,
            backgroundColor: 'rgba(255,255,255,0.8)',
            borderLeft: '1px solid rgba(0,0,0,0.5)'
          }} />
        </>
      )}
    </div>
  );
};

import { SamModel, AutoProcessor, RawImage, Tensor, env } from "@huggingface/transformers";

// CRITICAL: Configure environment BEFORE any model loading
// This prevents SecurityErrors in sandboxed iframes (no Cache API access)
env.allowLocalModels = false;
env.useBrowserCache = false;
env.backends.onnx.logLevel = 'fatal';

const MODEL_ID = "Xenova/slimsam-77-uniform";

class SamService {
  private model: any = null;
  private processor: any = null;
  private imageEmbeddings: any = null;
  private imageProcessed: any = null;
  private isLoaded = false;
  private loadPromise: Promise<void> | null = null;

  async load() {
    if (this.isLoaded) return;
    if (this.loadPromise) return this.loadPromise;

    this.loadPromise = (async () => {
      try {
        // Force specific config before loading
        env.allowLocalModels = false;
        env.useBrowserCache = false;

        // Use WebGPU if possible for speed, SAM models are heavy
        this.model = await SamModel.from_pretrained(MODEL_ID, {
          dtype: "fp16",
          device: "webgpu",
        });
        this.processor = await AutoProcessor.from_pretrained(MODEL_ID);
        this.isLoaded = true;
      } catch (err) {
        console.error("SAM Service load error:", err);
        // Fallback to CPU/WASM if WebGPU fails
        try {
          this.model = await SamModel.from_pretrained(MODEL_ID, {
            device: "wasm",
          });
          this.processor = await AutoProcessor.from_pretrained(MODEL_ID);
          this.isLoaded = true;
        } catch (wasmErr) {
          this.loadPromise = null;
          throw wasmErr;
        }
      }
    })();

    return this.loadPromise;
  }

  async setReferenceImage(url: string) {
    if (!this.model || !this.processor) await this.load();

    const image = await RawImage.fromURL(url);
    this.imageProcessed = await this.processor(image);
    this.imageEmbeddings = await this.model.get_image_embeddings(this.imageProcessed);

    return {
      width: image.width,
      height: image.height,
      originalSizes: this.imageProcessed.original_sizes,
      reshapedInputSizes: this.imageProcessed.reshaped_input_sizes
    };
  }

  async generateMask(point: { position: [number, number]; label: number }) {
    if (!this.model || !this.processor || !this.imageEmbeddings) {
      throw new Error("SAM Model or Embeddings not ready");
    }

    const reshaped = this.imageProcessed.reshaped_input_sizes[0];
    const scaledPoint = [
      point.position[0] * reshaped[1],
      point.position[1] * reshaped[0],
    ];

    const input_points = new Tensor("float32", scaledPoint, [1, 1, 1, 2]);
    const input_labels = new Tensor("int64", [BigInt(point.label)], [1, 1, 1]);

    const { pred_masks, iou_scores } = await this.model({
      ...this.imageEmbeddings,
      input_points,
      input_labels,
    });

    const masks = await this.processor.post_process_masks(
      pred_masks,
      this.imageProcessed.original_sizes,
      this.imageProcessed.reshaped_input_sizes,
    );

    return {
      mask: RawImage.fromTensor(masks[0][0]),
      scores: iou_scores.data as Float32Array
    };
  }

  clear() {
    this.imageEmbeddings = null;
    this.imageProcessed = null;
  }
}

export const samService = new SamService();

@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');
@import "tailwindcss";

@theme {
  --font-mono: "VT323", ui-monospace, SFMono-Regular, monospace;
}

@layer utilities {
  .bg-checkerboard {
    background-image: 
      linear-gradient(45deg, #e5e5e5 25%, transparent 25%, transparent 75%, #e5e5e5 75%, #e5e5e5),
      linear-gradient(45deg, #e5e5e5 25%, transparent 25%, transparent 75%, #e5e5e5 75%, #e5e5e5);
    background-color: #f5f5f5;
    background-size: 20px 20px;
    background-position: 0 0, 10px 10px;
  }

  .slider-thumb-retro::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 30px;
    background: #fff;
    border: 3px solid #000;
    cursor: pointer;
  }
  .slider-thumb-retro::-moz-range-thumb {
    width: 20px;
    height: 30px;
    background: #fff;
    border: 3px solid #000;
    cursor: pointer;
  }

  @keyframes scroll {
    0% { transform: translateX(100%); }
    100% { transform: translateX(-100%); }
  }

  @keyframes google-glow {
    0% { filter: drop-shadow(0 0 12px rgba(66, 133, 244, 0.8)); }
    33% { filter: drop-shadow(0 0 12px rgba(234, 67, 53, 0.8)); }
